// Parse the Python script's stdout (single JSON object) into structured
// summary fields the digest email + branching can consume. Everything
// stderr-side is preserved on item.json.raw_stderr for diagnostics.
const item = $input.first();
const stdout = (item.json.stdout || '').trim();
const stderr = (item.json.stderr || '').toString();
const exitCode = item.json.exitCode != null ? item.json.exitCode : -1;

let summary = null;
let parseError = null;
try {
  // The script may emit verbose stderr; stdout is the JSON payload.
  summary = JSON.parse(stdout);
} catch (e) {
  parseError = String(e).slice(0, 240);
}

if (!summary) {
  // Could not parse — treat as fatal. Email no-work / error notice.
  // We deliberately do NOT use the run-log `skip_reason` enum here — this
  // is n8n-internal state for the email branch, not a persisted run log.
  return [{ json: {
    top_status: 'parse_error',
    parse_failure: 'python_stdout_unparseable',
    parse_error: parseError,
    exitCode,
    raw_stderr: stderr.slice(0, 1000),
    raw_stdout: stdout.slice(0, 500),
    files_discovered: 0, files_with_content: 0,
    tasks_written: 0, notes_written: 0, articles_queued: 0,
    files_extracted: [], files_partial: [], files_error: [],
    files_by_state: { empty: 0, has_content: 0, scanning: 0, extracted: 0, partial: 0, error: 0 },
    reset_summary: { files_reset_full: 0, files_reset_partial: 0, files_reset_skipped: 0 },
  }}];
}

// Compute a coarse top-level status for the email branch.
const byState = summary.files_by_state || {};
const hasError = (byState.error || 0) > 0 || (summary.errors || []).length > 0;
const hasWork = (summary.files_with_content || 0) > 0;
let topStatus;
if (hasError) {
  topStatus = 'partial_or_error';
} else if (!hasWork) {
  topStatus = 'no_work';
} else {
  topStatus = 'success';
}

return [{ json: {
  ...summary,
  exitCode,
  raw_stderr_tail: stderr.split('\n').slice(-20).join('\n'),
  top_status: topStatus,
}}];
